// Aggregates the per-namespace dictionaries. Do not edit this file to add copy: add keys to messages/ru/<namespace>.ts and
// messages/en/<namespace>.ts (one file per area, so parallel work never collides). `ru` defines the key set; `en` is typed against it,
// so a key missing from English is a compile error as well as a failing unit test (lib/i18n.test.ts).
import { ruCommon } from "./ru/common";
import { ruHeader } from "./ru/header";
import { ruFooter } from "./ru/footer";
import { ruHome } from "./ru/home";
import { ruFeatures } from "./ru/features";
import { ruOwners } from "./ru/owners";
import { ruAbout } from "./ru/about";
import { ruBlog } from "./ru/blog";
import { ruContact } from "./ru/contact";
import { ruAuth } from "./ru/auth";
import { ruSearch } from "./ru/search";
import { ruVenue } from "./ru/venue";
import { ruBookings } from "./ru/bookings";
import { ruAccount } from "./ru/account";
import { ruErrors } from "./ru/errors";
import { enCommon } from "./en/common";
import { enHeader } from "./en/header";
import { enFooter } from "./en/footer";
import { enHome } from "./en/home";
import { enFeatures } from "./en/features";
import { enOwners } from "./en/owners";
import { enAbout } from "./en/about";
import { enBlog } from "./en/blog";
import { enContact } from "./en/contact";
import { enAuth } from "./en/auth";
import { enSearch } from "./en/search";
import { enVenue } from "./en/venue";
import { enBookings } from "./en/bookings";
import { enAccount } from "./en/account";
import { enErrors } from "./en/errors";

export const NAMESPACES = ["common", "header", "footer", "home", "features", "owners", "about", "blog", "contact", "auth", "search", "venue", "bookings", "account", "errors"] as const;

export const ru = {
  ...ruCommon,
  ...ruHeader,
  ...ruFooter,
  ...ruHome,
  ...ruFeatures,
  ...ruOwners,
  ...ruAbout,
  ...ruBlog,
  ...ruContact,
  ...ruAuth,
  ...ruSearch,
  ...ruVenue,
  ...ruBookings,
  ...ruAccount,
  ...ruErrors,
} as const;

export type MessageKey = keyof typeof ru;

export const en: Record<MessageKey, string> = {
  ...enCommon,
  ...enHeader,
  ...enFooter,
  ...enHome,
  ...enFeatures,
  ...enOwners,
  ...enAbout,
  ...enBlog,
  ...enContact,
  ...enAuth,
  ...enSearch,
  ...enVenue,
  ...enBookings,
  ...enAccount,
  ...enErrors,
};

export const DICTIONARIES: Record<"ru" | "en", Record<MessageKey, string>> = { ru, en };
